"""Membuat seluruh project trade-lens di folder tempat file ini berada.

Cara pakai (di Codespaces):
    python bootstrap.py
Setelah selesai, file ini boleh dihapus.
"""
import pathlib

FILES = {
    ".gitignore": ".venv/\n__pycache__/\n.pytest_cache/\n*.db\n*.db-wal\n*.db-shm\n.env\n",
    "README.md": "# trade-lens\n\nJurnal trading yang digabung dengan berita ekonomi AS secara realtime. Versi awal (first try).\n\n## Yang sudah ada\n\n- Form catat entry: instrumen, arah, harga, waktu, lot, SL, TP, catatan.\n- Konteks otomatis: berita N jam sebelum entry (default 5 jam), dibekukan saat trade dicatat.\n- Berita live lewat Server-Sent Events, dengan label delay di tiap item.\n- Worker yang polling connector. Saat ini baru Federal Reserve press release (RSS resmi).\n- Label status berita: resmi, dilaporkan, rumor.\n- Database SQLite satu file, tanpa setup tambahan.\n\n## Belum ada (roadmap)\n\n- Connector BLS (CPI, PPI, NFP), FRED, EIA, GDELT, dan kalender ekonomi.\n- Harga live XAUUSD dan perhitungan PnL.\n- Login dan multi-user.\n- Mode review: replay berita dan harga.\n\n## Menjalankan\n\nButuh Python 3.11 atau lebih baru.\n\n```bash\npython -m venv .venv\nsource .venv/bin/activate        # Windows: .venv\\Scripts\\activate\npip install -r requirements.txt\nuvicorn app.main:app --host 0.0.0.0 --port 8000 --workers 1\n```\n\nBuka http://localhost:8000. Di GitHub Codespaces, buka tab Ports lalu klik port 8000.\n\n`--workers 1` wajib. Broadcast live hanya berjalan dalam satu proses.\n\n## Tes\n\n```bash\npython -m pytest\n```\n\n## Konfigurasi (environment variable)\n\n| Variabel | Default | Fungsi |\n|---|---|---|\n| `TL_DB_PATH` | `trade_lens.db` | Lokasi file SQLite |\n| `TL_DISPLAY_TZ` | `Asia/Jakarta` | Zona waktu tampilan |\n| `TL_LOOKBACK_HOURS` | `5` | Berapa jam berita sebelum entry yang diambil |\n| `TL_ENABLE_WORKER` | `1` | Set `0` untuk mematikan polling connector |\n| `TL_USER_AGENT` | `trade-lens/0.1 ...` | User-Agent saat mengambil data. Isi dengan kontak kamu. |\n\n## Menambah connector baru\n\n1. Buat file di `app/connectors/`, misalnya `bls_calendar.py`.\n2. Implementasikan class yang mewarisi `Connector` dan mengembalikan list `NewsItem` dari `fetch()`.\n3. Daftarkan instance-nya di `app/connectors/__init__.py`.\n4. Tambahkan test kecil di `tests/`.\n\nAturan status: `official` hanya untuk sumber resmi pemerintah atau bank sentral. Laporan media memakai `reported`. Rumor atau berita yang belum terkonfirmasi memakai `rumor`.\n\n## Catatan jujur\n\n- URL feed Fed (`federalreserve.gov/feeds/press_all.xml`) perlu diverifikasi saat pertama dijalankan. Kalau 403 atau 404, cek User-Agent atau URL-nya.\n- Konteks dihitung dari berita yang sudah masuk sistem saat trade dicatat. Karena itu, catat trade sesegera mungkin setelah entry supaya konteksnya akurat.\n- GDELT hanya update sekitar 15 menit, jadi tidak memenuhi target delay 1-5 menit.\n\n## Lisensi dan etika data\n\n- Kode: MIT (ganti sesuai keputusan kamu).\n- Simpan judul, link, dan ringkasan pendek saja. Jangan menyimpan isi artikel penuh.\n- Setiap connector wajib mendokumentasikan ToS sumbernya.\n- Ini alat jurnal dan informasi, bukan saran investasi.\n",
    "app/__init__.py": "",
    "app/config.py": "\"\"\"Konfigurasi lewat environment variable. Default-nya cukup untuk development.\"\"\"\nimport os\nfrom dataclasses import dataclass\n\n\n@dataclass\nclass Settings:\n    db_path: str = os.getenv(\"TL_DB_PATH\", \"trade_lens.db\")\n    display_tz: str = os.getenv(\"TL_DISPLAY_TZ\", \"Asia/Jakarta\")\n    lookback_hours: int = int(os.getenv(\"TL_LOOKBACK_HOURS\", \"5\"))\n    enable_worker: bool = os.getenv(\"TL_ENABLE_WORKER\", \"1\") == \"1\"\n    user_agent: str = os.getenv(\n        \"TL_USER_AGENT\",\n        \"trade-lens/0.1 (open source; ganti dengan kontak kamu)\",\n    )\n\n\nsettings = Settings()\n",
    "app/connectors/__init__.py": "from .fed_rss import FedRSSConnector\n\n# Tambahkan connector baru di sini. Core tidak perlu diubah.\nCONNECTORS = [\n    FedRSSConnector(),\n]\n",
    "app/connectors/base.py": "from __future__ import annotations\n\nfrom abc import ABC, abstractmethod\nfrom dataclasses import dataclass\nfrom datetime import datetime\n\nimport httpx\n\n\n@dataclass\nclass NewsItem:\n    external_id: str            # id unik dari sumber, dipakai untuk dedup\n    source: str                 # nama tampilan, mis. \"Federal Reserve\"\n    title: str\n    published_at: datetime      # wajib timezone-aware (UTC)\n    url: str | None = None\n    summary: str | None = None  # ringkasan pendek saja, jangan isi artikel penuh\n    tier: int = 2               # 1 = resmi, 2 = media terpercaya, 3 = konteks/agregator\n    status: str = \"reported\"    # \"official\" | \"reported\" | \"rumor\"\n\n\nclass Connector(ABC):\n    name: str = \"base\"\n    interval_seconds: int = 60\n\n    @abstractmethod\n    async def fetch(self, client: httpx.AsyncClient) -> list[NewsItem]:\n        \"\"\"Ambil item terbaru dari sumber. Dedup dilakukan oleh storage, bukan di sini.\"\"\"\n",
    "app/connectors/fed_rss.py": "from __future__ import annotations\n\nimport re\nfrom datetime import datetime, timezone\n\nimport feedparser\nimport httpx\n\nfrom .base import Connector, NewsItem\n\n# Feed press release resmi The Fed. Cek ulang URL ini saat pertama dijalankan.\nFED_PRESS_RSS = \"https://www.federalreserve.gov/feeds/press_all.xml\"\n\n\ndef _strip_html(text: str | None) -> str:\n    text = re.sub(r\"<[^>]+>\", \" \", text or \"\")\n    text = re.sub(r\"\\s+\", \" \", text).strip()\n    return text[:400]\n\n\ndef _published_utc(entry) -> datetime:\n    parsed = entry.get(\"published_parsed\") or entry.get(\"updated_parsed\")\n    if parsed:\n        return datetime(*parsed[:6], tzinfo=timezone.utc)\n    return datetime.now(timezone.utc)\n\n\nclass FedRSSConnector(Connector):\n    name = \"fed_rss\"\n    interval_seconds = 60\n\n    async def fetch(self, client: httpx.AsyncClient) -> list[NewsItem]:\n        resp = await client.get(FED_PRESS_RSS, timeout=20)\n        resp.raise_for_status()\n        feed = feedparser.parse(resp.text)\n\n        items: list[NewsItem] = []\n        for e in feed.entries:\n            link = e.get(\"link\")\n            items.append(\n                NewsItem(\n                    external_id=f\"fed:{e.get('id') or link}\",\n                    source=\"Federal Reserve\",\n                    title=(e.get(\"title\") or \"\").strip(),\n                    url=link,\n                    summary=_strip_html(e.get(\"summary\")),\n                    published_at=_published_utc(e),\n                    tier=1,\n                    status=\"official\",\n                )\n            )\n        return items\n",
    "app/db.py": "\"\"\"SQLite sederhana. Satu koneksi per pemanggilan, aman dipakai dari thread mana pun.\"\"\"\nimport sqlite3\nfrom contextlib import contextmanager\n\nfrom .config import settings\n\nSCHEMA = \"\"\"\nCREATE TABLE IF NOT EXISTS news (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    external_id TEXT NOT NULL UNIQUE,\n    source TEXT NOT NULL,\n    tier INTEGER NOT NULL,\n    status TEXT NOT NULL,\n    title TEXT NOT NULL,\n    url TEXT,\n    summary TEXT,\n    tags TEXT NOT NULL DEFAULT '',\n    impact INTEGER NOT NULL DEFAULT 0,\n    published_at TEXT NOT NULL,\n    ingested_at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_news_published ON news(published_at);\n\nCREATE TABLE IF NOT EXISTS trades (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    instrument TEXT NOT NULL DEFAULT 'XAUUSD',\n    direction TEXT NOT NULL CHECK (direction IN ('long', 'short')),\n    entry_price REAL NOT NULL,\n    entry_time TEXT NOT NULL,\n    lot REAL,\n    sl REAL,\n    tp REAL,\n    note TEXT NOT NULL DEFAULT '',\n    context_json TEXT NOT NULL DEFAULT '[]',\n    created_at TEXT NOT NULL\n);\n\"\"\"\n\n\ndef _connect() -> sqlite3.Connection:\n    conn = sqlite3.connect(settings.db_path, check_same_thread=False, timeout=10)\n    conn.row_factory = sqlite3.Row\n    return conn\n\n\ndef init_db() -> None:\n    conn = _connect()\n    try:\n        conn.execute(\"PRAGMA journal_mode=WAL\")\n        conn.executescript(SCHEMA)\n        conn.commit()\n    finally:\n        conn.close()\n\n\n@contextmanager\ndef get_db():\n    conn = _connect()\n    try:\n        yield conn\n        conn.commit()\n    except Exception:\n        conn.rollback()\n        raise\n    finally:\n        conn.close()\n",
    "app/main.py": "\"\"\"Entry point. Jalankan: uvicorn app.main:app --workers 1\"\"\"\nimport asyncio\nimport json\nfrom contextlib import asynccontextmanager\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom zoneinfo import ZoneInfo\n\nfrom fastapi import FastAPI, Form, HTTPException, Request\nfrom fastapi.responses import HTMLResponse, RedirectResponse, StreamingResponse\nfrom fastapi.staticfiles import StaticFiles\nfrom fastapi.templating import Jinja2Templates\n\nfrom .config import settings\nfrom .db import get_db, init_db\nfrom .services import live\nfrom .services.context import build_context\nfrom .services.news import news_view\nfrom .timeutil import fmt_utc, to_local\nfrom .worker import run_worker\n\nBASE_DIR = Path(__file__).resolve().parent\n\ntemplates = Jinja2Templates(directory=str(BASE_DIR / \"templates\"))\ntemplates.env.filters[\"to_local\"] = to_local\n\n\n@asynccontextmanager\nasync def lifespan(_: FastAPI):\n    init_db()\n    worker = asyncio.create_task(run_worker()) if settings.enable_worker else None\n    yield\n    if worker:\n        worker.cancel()\n\n\napp = FastAPI(title=\"trade-lens\", lifespan=lifespan)\napp.mount(\"/static\", StaticFiles(directory=str(BASE_DIR / \"static\")), name=\"static\")\n\n\n# ---------- helper input ----------\n\ndef _parse_float(value: str, label: str, required: bool = False) -> float | None:\n    value = (value or \"\").strip().replace(\",\", \".\")\n    if not value:\n        if required:\n            raise HTTPException(400, f\"{label} wajib diisi\")\n        return None\n    try:\n        return float(value)\n    except ValueError:\n        raise HTTPException(400, f\"{label} harus berupa angka\") from None\n\n\ndef _local_to_utc(value: str) -> datetime:\n    try:\n        naive = datetime.fromisoformat(value)\n    except ValueError:\n        raise HTTPException(400, \"Format waktu entry tidak valid\") from None\n    return naive.replace(tzinfo=ZoneInfo(settings.display_tz)).astimezone(timezone.utc)\n\n\n# ---------- halaman ----------\n\n@app.get(\"/\", response_class=HTMLResponse)\ndef dashboard(request: Request):\n    with get_db() as db:\n        trades = db.execute(\"SELECT * FROM trades ORDER BY entry_time DESC LIMIT 50\").fetchall()\n        news = db.execute(\"SELECT * FROM news ORDER BY published_at DESC LIMIT 30\").fetchall()\n    now_local = datetime.now(ZoneInfo(settings.display_tz)).strftime(\"%Y-%m-%dT%H:%M\")\n    return templates.TemplateResponse(\n        request,\n        \"index.html\",\n        {\n            \"trades\": [dict(t) for t in trades],\n            \"news\": [news_view(n) for n in news],\n            \"default_entry\": now_local,\n            \"tz\": settings.display_tz,\n        },\n    )\n\n\n@app.get(\"/trades/{trade_id}\", response_class=HTMLResponse)\ndef trade_detail(request: Request, trade_id: int):\n    with get_db() as db:\n        row = db.execute(\"SELECT * FROM trades WHERE id = ?\", (trade_id,)).fetchone()\n        if row is None:\n            raise HTTPException(404, \"Trade tidak ditemukan\")\n        after = db.execute(\n            \"SELECT * FROM news WHERE published_at > ? ORDER BY published_at DESC LIMIT 200\",\n            (row[\"entry_time\"],),\n        ).fetchall()\n    trade = dict(row)\n    return templates.TemplateResponse(\n        request,\n        \"trade.html\",\n        {\n            \"trade\": trade,\n            \"context\": [news_view(n) for n in json.loads(trade[\"context_json\"])],\n            \"after\": [news_view(n) for n in after],\n            \"lookback\": settings.lookback_hours,\n            \"tz\": settings.display_tz,\n        },\n    )\n\n\n# ---------- aksi ----------\n\n@app.post(\"/trades\")\ndef create_trade(\n    instrument: str = Form(\"XAUUSD\"),\n    direction: str = Form(...),\n    entry_price: str = Form(...),\n    entry_time: str = Form(...),\n    lot: str = Form(\"\"),\n    sl: str = Form(\"\"),\n    tp: str = Form(\"\"),\n    note: str = Form(\"\"),\n):\n    if direction not in (\"long\", \"short\"):\n        raise HTTPException(400, \"Arah harus long atau short\")\n    price = _parse_float(entry_price, \"Harga entry\", required=True)\n    if price <= 0:\n        raise HTTPException(400, \"Harga entry harus lebih dari 0\")\n\n    entry_utc = _local_to_utc(entry_time)\n    now = datetime.now(timezone.utc)\n    context = build_context(entry_utc, known_at=now)\n\n    with get_db() as db:\n        cur = db.execute(\n            \"\"\"INSERT INTO trades\n               (instrument, direction, entry_price, entry_time, lot, sl, tp, note,\n                context_json, created_at)\n               VALUES (?,?,?,?,?,?,?,?,?,?)\"\"\",\n            (\n                instrument.strip().upper() or \"XAUUSD\",\n                direction,\n                price,\n                fmt_utc(entry_utc),\n                _parse_float(lot, \"Lot\"),\n                _parse_float(sl, \"SL\"),\n                _parse_float(tp, \"TP\"),\n                note.strip(),\n                json.dumps(context),\n                fmt_utc(now),\n            ),\n        )\n        trade_id = cur.lastrowid\n    return RedirectResponse(f\"/trades/{trade_id}\", status_code=303)\n\n\n@app.post(\"/trades/{trade_id}/delete\")\ndef delete_trade(trade_id: int):\n    with get_db() as db:\n        db.execute(\"DELETE FROM trades WHERE id = ?\", (trade_id,))\n    return RedirectResponse(\"/\", status_code=303)\n\n\n# ---------- realtime & kesehatan ----------\n\n@app.get(\"/stream/news\")\nasync def stream_news(request: Request):\n    queue = live.subscribe()\n    item_template = templates.get_template(\"partials/news_item.html\")\n\n    async def event_source():\n        try:\n            yield \": connected\\n\\n\"\n            while True:\n                if await request.is_disconnected():\n                    break\n                try:\n                    row = await asyncio.wait_for(queue.get(), timeout=15)\n                except asyncio.TimeoutError:\n                    yield \": ping\\n\\n\"\n                    continue\n                html = item_template.render(item=news_view(row))\n                html = \" \".join(html.split())  # satu baris agar aman untuk SSE\n                yield f\"event: news\\ndata: {html}\\n\\n\"\n        finally:\n            live.unsubscribe(queue)\n\n    return StreamingResponse(\n        event_source(),\n        media_type=\"text/event-stream\",\n        headers={\"Cache-Control\": \"no-cache\", \"X-Accel-Buffering\": \"no\"},\n    )\n\n\n@app.get(\"/health\")\ndef health():\n    return {\"ok\": True}\n",
    "app/services/__init__.py": "",
    "app/services/context.py": "from __future__ import annotations\n\nfrom datetime import datetime, timedelta\n\nfrom ..config import settings\nfrom ..db import get_db\nfrom ..timeutil import fmt_utc\n\nSNAPSHOT_LIMIT = 100\n\n\ndef build_context(entry_utc: datetime, known_at: datetime) -> list[dict]:\n    \"\"\"Berita dengan published_at di window [entry - N jam, entry] yang sudah masuk sistem pada known_at.\n\n    known_at membatasi snapshot hanya pada apa yang benar-benar terlihat saat trade dicatat,\n    jadi berita yang baru masuk belakangan tidak ikut.\n    \"\"\"\n    start = entry_utc - timedelta(hours=settings.lookback_hours)\n    with get_db() as db:\n        rows = db.execute(\n            \"\"\"SELECT * FROM news\n               WHERE published_at >= ? AND published_at <= ?\n                 AND ingested_at <= ?\n               ORDER BY published_at DESC\n               LIMIT ?\"\"\",\n            (fmt_utc(start), fmt_utc(entry_utc), fmt_utc(known_at), SNAPSHOT_LIMIT),\n        ).fetchall()\n    return [dict(r) for r in rows]\n",
    "app/services/live.py": "\"\"\"Broadcast in-process ke semua klien SSE yang sedang terhubung.\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\n\n_subscribers: set[asyncio.Queue] = set()\n\n\ndef subscribe() -> asyncio.Queue:\n    queue: asyncio.Queue = asyncio.Queue(maxsize=200)\n    _subscribers.add(queue)\n    return queue\n\n\ndef unsubscribe(queue: asyncio.Queue) -> None:\n    _subscribers.discard(queue)\n\n\ndef publish(item: dict) -> None:\n    for queue in list(_subscribers):\n        try:\n            queue.put_nowait(item)\n        except asyncio.QueueFull:\n            pass  # klien terlalu lambat, dibuang supaya worker tidak macet\n",
    "app/services/news.py": "from __future__ import annotations\n\nfrom datetime import datetime, timezone\nfrom typing import Iterable\n\nfrom ..connectors.base import NewsItem\nfrom ..db import get_db\nfrom ..timeutil import fmt_utc, parse_utc\nfrom .tagging import impact_score, tag_text\n\n\ndef save_items(items: Iterable[NewsItem], ingested_at: datetime | None = None) -> list[dict]:\n    \"\"\"Simpan item baru dan lewati yang sudah ada. Mengembalikan hanya row yang benar-benar baru.\"\"\"\n    ingested_at = ingested_at or datetime.now(timezone.utc)\n    new_rows: list[dict] = []\n    with get_db() as db:\n        for it in items:\n            tags = tag_text(f\"{it.title} {it.summary or ''}\")\n            cur = db.execute(\n                \"\"\"INSERT OR IGNORE INTO news\n                   (external_id, source, tier, status, title, url, summary,\n                    tags, impact, published_at, ingested_at)\n                   VALUES (?,?,?,?,?,?,?,?,?,?,?)\"\"\",\n                (\n                    it.external_id, it.source, it.tier, it.status, it.title,\n                    it.url, it.summary, \",\".join(tags), impact_score(it.tier, tags),\n                    fmt_utc(it.published_at), fmt_utc(ingested_at),\n                ),\n            )\n            if cur.rowcount == 1:\n                row = db.execute(\"SELECT * FROM news WHERE id = ?\", (cur.lastrowid,)).fetchone()\n                new_rows.append(dict(row))\n    return new_rows\n\n\ndef news_view(row) -> dict:\n    \"\"\"Ubah row atau dict berita menjadi bentuk siap-render: tags list, delay, dan url yang aman.\"\"\"\n    d = dict(row)\n    d[\"tags_list\"] = [t for t in (d.get(\"tags\") or \"\").split(\",\") if t]\n    url = d.get(\"url\") or \"\"\n    d[\"url\"] = url if url.startswith((\"http://\", \"https://\")) else None\n    try:\n        delta = parse_utc(d[\"ingested_at\"]) - parse_utc(d[\"published_at\"])\n        d[\"delay_min\"] = round(delta.total_seconds() / 60, 1)\n    except (KeyError, TypeError, ValueError):\n        d[\"delay_min\"] = None\n    return d\n",
    "app/services/tagging.py": "\"\"\"Tagging sederhana berbasis kata kunci dan skor dampak. Kontributor bisa menambah kata kunci di sini.\"\"\"\nfrom __future__ import annotations\n\nimport re\n\nKEYWORDS: dict[str, list[str]] = {\n    \"gold\": [\"gold\", \"xau\", \"bullion\"],\n    \"oil\": [\"oil\", \"crude\", \"wti\", \"brent\", \"opec\"],\n    \"fed\": [\"fomc\", \"federal reserve\", \"powell\", \"rate decision\", \"interest rate\"],\n    \"inflation\": [\"cpi\", \"ppi\", \"pce\", \"inflation\"],\n    \"jobs\": [\"nonfarm\", \"payrolls\", \"unemployment\", \"jobs report\"],\n    \"dollar\": [\"dollar\", \"dxy\", \"treasury yields\", \"yields\"],\n    \"geopolitics\": [\"war\", \"iran\", \"israel\", \"ukraine\", \"russia\", \"sanctions\", \"missile\", \"conflict\"],\n    \"trump\": [\"trump\", \"tariff\", \"tariffs\"],\n}\n\n\ndef tag_text(text: str) -> list[str]:\n    low = text.lower()\n    return [\n        tag\n        for tag, words in KEYWORDS.items()\n        if any(re.search(rf\"\\b{re.escape(w)}\\b\", low) for w in words)\n    ]\n\n\ndef impact_score(tier: int, tags: list[str]) -> int:\n    base = {1: 60, 2: 40}.get(tier, 20)\n    return min(100, base + 8 * len(tags))\n",
    "app/static/app.js": "(function () {\n  const feed = document.getElementById(\"live-feed\");\n  const status = document.getElementById(\"live-status\");\n  if (!feed || !window.EventSource) return;\n\n  const setStatus = (text) => { if (status) status.textContent = text; };\n  const es = new EventSource(\"/stream/news\");\n\n  es.onopen = () => setStatus(\"tersambung\");\n  es.onerror = () => setStatus(\"menyambung ulang\");\n\n  es.addEventListener(\"news\", (e) => {\n    const empty = feed.querySelector(\".empty\");\n    if (empty) empty.remove();\n    feed.insertAdjacentHTML(\"afterbegin\", e.data);\n  });\n})();\n",
    "app/static/style.css": "/* Terminal-ish, tapi dibuat sendiri: serif untuk judul berita, sans untuk data.\n   Status berita dibedakan lewat garis kiri (solid, biru-abu, putus-putus) agar terbaca sekilas. */\n\n:root {\n  --bg: #0d1219;\n  --surface: #141c27;\n  --rule: #26334a;\n  --ink: #e6ebf2;\n  --muted: #8795a8;\n  --rumor: #d9a441;\n  --short: #e27d6a;\n  --long: #6fbf94;\n  --serif: \"Source Serif 4\", Georgia, \"Times New Roman\", serif;\n  --sans: \"Hanken Grotesk\", system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n}\n\n*, *::before, *::after { box-sizing: border-box; }\nhtml { color-scheme: dark; }\n\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--ink);\n  font: 15px/1.55 var(--sans);\n  -webkit-font-smoothing: antialiased;\n}\n\na { color: inherit; }\n\n:focus-visible {\n  outline: 2px solid var(--ink);\n  outline-offset: 2px;\n}\n\n.topbar {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 14px 16px;\n  border-bottom: 1px solid var(--rule);\n}\n.brand { font: 600 18px/1 var(--serif); text-decoration: none; }\n.tz { color: var(--muted); font-size: 13px; font-variant-numeric: tabular-nums; }\n\n.wrap { max-width: 1280px; margin: 0 auto; padding: 16px; }\n.layout { display: grid; gap: 28px; }\n.pane { min-width: 0; }\n\nh1 { font: 600 26px/1.2 var(--serif); margin: 6px 0 14px; }\nh2 { font: 600 18px/1.3 var(--serif); margin: 0 0 10px; }\nh3 { font: 600 17px/1.35 var(--serif); margin: 4px 0; }\n.section { margin-top: 24px; padding-top: 16px; border-top: 1px solid var(--rule); }\n\n.form { display: grid; gap: 12px; }\n.form label { display: grid; gap: 4px; font-size: 13px; color: var(--muted); }\n.form input,\n.form select,\n.form textarea {\n  width: 100%;\n  font: 16px var(--sans); /* 16px supaya iOS tidak zoom saat input difokus */\n  color: var(--ink);\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 2px;\n  padding: 10px 11px;\n  font-variant-numeric: tabular-nums;\n}\n.fields-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n.fields-3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }\n\nbutton {\n  font: 600 15px var(--sans);\n  color: var(--bg);\n  background: var(--ink);\n  border: 0;\n  border-radius: 2px;\n  padding: 12px;\n  width: 100%;\n  cursor: pointer;\n}\nbutton.ghost {\n  width: auto;\n  padding: 8px 12px;\n  background: transparent;\n  color: var(--short);\n  border: 1px solid var(--rule);\n  font-weight: 500;\n}\n.danger-zone { margin-top: 32px; }\n\n.trades { list-style: none; margin: 0; padding: 0; }\n.trades li { border-top: 1px solid var(--rule); }\n.trades a {\n  display: grid;\n  grid-template-columns: auto 1fr auto;\n  gap: 12px;\n  align-items: baseline;\n  padding: 11px 0;\n  text-decoration: none;\n}\n.trades a:hover .price { text-decoration: underline; text-underline-offset: 3px; }\n\n.dir { font-weight: 600; font-size: 14px; }\n.dir.long { color: var(--long); }\n.dir.short { color: var(--short); }\n.price { font-variant-numeric: tabular-nums; font-weight: 600; }\n.when { color: var(--muted); font-size: 13px; text-align: right; font-variant-numeric: tabular-nums; }\n\n.facts {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 12px 16px;\n  margin: 14px 0;\n}\n.facts dt { font-size: 12px; color: var(--muted); }\n.facts dd { margin: 2px 0 0; font-size: 16px; font-variant-numeric: tabular-nums; }\n.note { color: #aeb8c6; margin: 0 0 8px; }\n.back { margin: 0; font-size: 13px; }\n.back a { color: var(--muted); }\n\n.entry-marker {\n  display: flex;\n  align-items: baseline;\n  gap: 12px;\n  padding: 10px 0;\n  border-top: 2px solid var(--ink);\n  border-bottom: 1px solid var(--rule);\n  font-weight: 600;\n}\n.entry-marker .when { margin-left: auto; font-weight: 400; }\n\n.news {\n  padding: 12px 0 12px 12px;\n  border-bottom: 1px solid var(--rule);\n  border-left: 2px solid var(--rule);\n}\n.news.official { border-left-color: var(--ink); }\n.news.reported { border-left-color: #6f88a8; }\n.news.rumor { border-left: 2px dashed var(--rumor); }\n\n.news h3 a { text-decoration: none; }\n.news h3 a:hover { text-decoration: underline; text-underline-offset: 3px; }\n.news p { margin: 4px 0 0; color: #aeb8c6; font-size: 14px; }\n\n.meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 2px 12px;\n  font-size: 12px;\n  color: var(--muted);\n  font-variant-numeric: tabular-nums;\n}\n.status { font-weight: 600; }\n.status.official { color: var(--ink); }\n.status.reported { color: #8fa9cc; }\n.status.rumor { color: var(--rumor); }\n\n.tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; font-size: 12px; color: var(--muted); }\n.tags span { border: 1px solid var(--rule); padding: 0 6px; border-radius: 2px; }\n\n.muted { color: var(--muted); font-size: 13px; font-weight: 400; }\n.empty { color: var(--muted); margin: 8px 0; }\n\n@media (min-width: 600px) {\n  .facts { grid-template-columns: repeat(4, minmax(0, 1fr)); }\n}\n\n@media (min-width: 960px) {\n  .layout { grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr); align-items: start; }\n  .wire-pane {\n    position: sticky;\n    top: 16px;\n    max-height: calc(100vh - 32px);\n    overflow-y: auto;\n    padding-right: 4px;\n  }\n}\n",
    "app/templates/base.html": "<!doctype html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"theme-color\" content=\"#0d1219\">\n  <title>{% block title %}trade-lens{% endblock %}</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Hanken+Grotesk:wght@400;500;600&family=Source+Serif+4:opsz,wght@8..60,500;8..60,600&display=swap\">\n  <link rel=\"stylesheet\" href=\"/static/style.css\">\n</head>\n<body>\n  <header class=\"topbar\">\n    <a class=\"brand\" href=\"/\">trade-lens</a>\n    <span class=\"tz\">Zona waktu {{ tz|default('') }}</span>\n  </header>\n  <main class=\"wrap\">\n    {% block content %}{% endblock %}\n  </main>\n  <script src=\"/static/app.js\" defer></script>\n</body>\n</html>\n",
    "app/templates/index.html": "{% extends \"base.html\" %}\n{% block content %}\n<div class=\"layout\">\n  <div class=\"pane\">\n    <section>\n      <h1>Catat entry</h1>\n      <form method=\"post\" action=\"/trades\" class=\"form\">\n        <div class=\"fields-2\">\n          <label>Instrumen\n            <input name=\"instrument\" value=\"XAUUSD\" autocomplete=\"off\" required>\n          </label>\n          <label>Arah\n            <select name=\"direction\">\n              <option value=\"long\">Long</option>\n              <option value=\"short\">Short</option>\n            </select>\n          </label>\n        </div>\n        <label>Harga entry\n          <input name=\"entry_price\" inputmode=\"decimal\" placeholder=\"2650.50\" required>\n        </label>\n        <label>Waktu entry ({{ tz }})\n          <input type=\"datetime-local\" name=\"entry_time\" value=\"{{ default_entry }}\" required>\n        </label>\n        <div class=\"fields-3\">\n          <label>Lot <input name=\"lot\" inputmode=\"decimal\"></label>\n          <label>SL <input name=\"sl\" inputmode=\"decimal\"></label>\n          <label>TP <input name=\"tp\" inputmode=\"decimal\"></label>\n        </div>\n        <label>Catatan\n          <textarea name=\"note\" rows=\"2\"></textarea>\n        </label>\n        <button type=\"submit\">Simpan trade</button>\n      </form>\n    </section>\n\n    <section class=\"section\">\n      <h2>Trade tercatat</h2>\n      {% if trades %}\n      <ul class=\"trades\">\n        {% for t in trades %}\n        <li>\n          <a href=\"/trades/{{ t.id }}\">\n            <span class=\"dir {{ t.direction }}\">{{ t.direction|capitalize }}</span>\n            <span><span class=\"price\">{{ '%.2f'|format(t.entry_price) }}</span> {{ t.instrument }}</span>\n            <span class=\"when\">{{ t.entry_time|to_local }}</span>\n          </a>\n        </li>\n        {% endfor %}\n      </ul>\n      {% else %}\n      <p class=\"empty\">Belum ada trade. Catat entry pertama lewat form di atas.</p>\n      {% endif %}\n    </section>\n  </div>\n\n  <aside class=\"pane wire-pane\">\n    <h2>Berita terbaru <span id=\"live-status\" class=\"muted\">menghubungkan</span></h2>\n    <div id=\"live-feed\" class=\"wire\">\n      {% for item in news %}{% include \"partials/news_item.html\" %}\n      {% else %}<p class=\"empty\">Belum ada berita. Worker sedang mengambil data pertama.</p>{% endfor %}\n    </div>\n  </aside>\n</div>\n{% endblock %}\n",
    "app/templates/partials/news_item.html": "<article class=\"news {{ item.status }}\">\n  <div class=\"meta\">\n    <span class=\"status {{ item.status }}\">{{ {'official': 'resmi', 'reported': 'dilaporkan', 'rumor': 'rumor'}.get(item.status, item.status) }}</span>\n    <span>{{ item.source }}</span>\n    <time>{{ item.published_at|to_local }}</time>\n    {% if item.delay_min is not none %}<span title=\"Selisih waktu terbit ke waktu masuk sistem\">delay {{ item.delay_min }} mnt</span>{% endif %}\n    <span>dampak {{ item.impact }}</span>\n  </div>\n  <h3>\n    {% if item.url %}<a href=\"{{ item.url }}\" target=\"_blank\" rel=\"noopener noreferrer\">{{ item.title }}</a>{% else %}{{ item.title }}{% endif %}\n  </h3>\n  {% if item.summary %}<p>{{ item.summary }}</p>{% endif %}\n  {% if item.tags_list %}\n  <div class=\"tags\">{% for t in item.tags_list %}<span>{{ t }}</span>{% endfor %}</div>\n  {% endif %}\n</article>\n",
    "app/templates/trade.html": "{% extends \"base.html\" %}\n{% block title %}{{ trade.instrument }} {{ trade.direction }} · trade-lens{% endblock %}\n{% block content %}\n<p class=\"back\"><a href=\"/\">Kembali ke daftar</a></p>\n<h1>{{ trade.direction|capitalize }} {{ trade.instrument }} di {{ '%.2f'|format(trade.entry_price) }}</h1>\n\n<dl class=\"facts\">\n  <div><dt>Waktu entry</dt><dd>{{ trade.entry_time|to_local }}</dd></div>\n  <div><dt>Lot</dt><dd>{{ trade.lot if trade.lot is not none else '–' }}</dd></div>\n  <div><dt>SL</dt><dd>{{ trade.sl if trade.sl is not none else '–' }}</dd></div>\n  <div><dt>TP</dt><dd>{{ trade.tp if trade.tp is not none else '–' }}</dd></div>\n</dl>\n{% if trade.note %}<p class=\"note\">{{ trade.note }}</p>{% endif %}\n\n<div class=\"layout\">\n  <div class=\"pane\">\n    <h2>{{ lookback }} jam sebelum entry</h2>\n    <p class=\"muted\">Berita yang sudah masuk sistem saat trade dicatat. Tidak berubah walau sumbernya di-update.</p>\n    <div class=\"timeline\">\n      <div class=\"entry-marker\">\n        <span class=\"price\">{{ '%.2f'|format(trade.entry_price) }}</span>\n        <span>Entry</span>\n        <span class=\"when\">{{ trade.entry_time|to_local }}</span>\n      </div>\n      {% for item in context %}{% include \"partials/news_item.html\" %}\n      {% else %}<p class=\"empty\">Tidak ada berita di window ini.</p>{% endfor %}\n    </div>\n  </div>\n\n  <aside class=\"pane wire-pane\">\n    <h2>Setelah entry <span id=\"live-status\" class=\"muted\">menghubungkan</span></h2>\n    <div id=\"live-feed\" class=\"wire\">\n      {% for item in after %}{% include \"partials/news_item.html\" %}\n      {% else %}<p class=\"empty\">Belum ada berita setelah entry.</p>{% endfor %}\n    </div>\n  </aside>\n</div>\n\n<form method=\"post\" action=\"/trades/{{ trade.id }}/delete\" class=\"danger-zone\" onsubmit=\"return confirm('Hapus trade ini?')\">\n  <button class=\"ghost\" type=\"submit\">Hapus trade</button>\n</form>\n{% endblock %}\n",
    "app/timeutil.py": "\"\"\"Semua waktu disimpan dalam UTC dengan format sortable. Tampilan mengikuti display_tz.\"\"\"\nfrom __future__ import annotations\n\nfrom datetime import datetime, timezone\nfrom zoneinfo import ZoneInfo\n\nfrom .config import settings\n\nUTC_FMT = \"%Y-%m-%dT%H:%M:%SZ\"\nMONTHS_ID = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"Mei\", \"Jun\", \"Jul\", \"Agu\", \"Sep\", \"Okt\", \"Nov\", \"Des\"]\n\n\ndef fmt_utc(dt: datetime) -> str:\n    return dt.astimezone(timezone.utc).strftime(UTC_FMT)\n\n\ndef parse_utc(value: str) -> datetime:\n    return datetime.strptime(value, UTC_FMT).replace(tzinfo=timezone.utc)\n\n\ndef to_local(value: str | datetime) -> str:\n    dt = value if isinstance(value, datetime) else parse_utc(value)\n    local = dt.astimezone(ZoneInfo(settings.display_tz))\n    return f\"{local.day} {MONTHS_ID[local.month - 1]} {local:%H:%M}\"\n",
    "app/worker.py": "\"\"\"Worker background: polling semua connector, menyimpan item baru, lalu menyiarkannya.\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\nimport logging\n\nimport httpx\n\nfrom .config import settings\nfrom .connectors import CONNECTORS\nfrom .connectors.base import Connector\nfrom .services import live\nfrom .services.news import save_items\n\nlog = logging.getLogger(\"trade_lens.worker\")\n\n\nasync def _poll(connector: Connector, client: httpx.AsyncClient) -> None:\n    first_run = True\n    while True:\n        try:\n            items = await connector.fetch(client)\n            new_rows = await asyncio.to_thread(save_items, items)\n            if new_rows:\n                log.info(\"%s: %d item baru\", connector.name, len(new_rows))\n            # Pada run pertama, item lama hanya disimpan. Tidak disiarkan sebagai \"live\".\n            if not first_run:\n                for row in new_rows:\n                    live.publish(row)\n            first_run = False\n        except Exception:\n            log.exception(\"connector %s gagal, dicoba lagi\", connector.name)\n        await asyncio.sleep(connector.interval_seconds)\n\n\nasync def run_worker() -> None:\n    headers = {\n        \"User-Agent\": settings.user_agent,\n        \"Accept\": \"application/rss+xml, application/xml;q=0.9, */*;q=0.8\",\n    }\n    async with httpx.AsyncClient(headers=headers, follow_redirects=True) as client:\n        await asyncio.gather(*(_poll(c, client) for c in CONNECTORS))\n",
    "pytest.ini": "[pytest]\npythonpath = .\ntestpaths = tests\n",
    "requirements.txt": "fastapi>=0.110\nuvicorn[standard]>=0.29\njinja2>=3.1\npython-multipart>=0.0.9\nhttpx>=0.27\nfeedparser>=6.0\ntzdata>=2024.1\npytest>=8.0\n",
    "tests/test_app.py": "import pytest\nfrom fastapi.testclient import TestClient\n\nfrom app.config import settings\n\n\n@pytest.fixture\ndef client(tmp_path, monkeypatch):\n    monkeypatch.setattr(settings, \"db_path\", str(tmp_path / \"app.db\"))\n    monkeypatch.setattr(settings, \"enable_worker\", False)\n    from app.main import app\n\n    with TestClient(app) as c:\n        yield c\n\n\ndef test_dashboard_renders(client):\n    r = client.get(\"/\")\n    assert r.status_code == 200\n    assert \"Catat entry\" in r.text\n\n\ndef test_create_and_view_trade(client):\n    r = client.post(\n        \"/trades\",\n        data={\n            \"instrument\": \"xauusd\",\n            \"direction\": \"long\",\n            \"entry_price\": \"2650.5\",\n            \"entry_time\": \"2026-10-16T14:30\",\n            \"lot\": \"\",\n            \"sl\": \"2640\",\n            \"tp\": \"\",\n            \"note\": \"tes\",\n        },\n        follow_redirects=False,\n    )\n    assert r.status_code == 303\n    detail = client.get(r.headers[\"location\"])\n    assert detail.status_code == 200\n    assert \"XAUUSD\" in detail.text\n\n\ndef test_invalid_direction_rejected(client):\n    r = client.post(\n        \"/trades\",\n        data={\"direction\": \"sideways\", \"entry_price\": \"1\", \"entry_time\": \"2026-10-16T14:30\"},\n    )\n    assert r.status_code == 400\n\n\ndef test_health(client):\n    assert client.get(\"/health\").json() == {\"ok\": True}\n",
    "tests/test_context.py": "from datetime import datetime, timedelta, timezone\n\nfrom app.config import settings\nfrom app.connectors.base import NewsItem\nfrom app.db import init_db\nfrom app.services.context import build_context\nfrom app.services.news import save_items\n\nUTC = timezone.utc\n\n\ndef _item(ext, title, published):\n    return NewsItem(external_id=ext, source=\"Test\", title=title,\n                    published_at=published, tier=1, status=\"official\")\n\n\ndef test_context_window_and_known_at(tmp_path, monkeypatch):\n    monkeypatch.setattr(settings, \"db_path\", str(tmp_path / \"ctx.db\"))\n    monkeypatch.setattr(settings, \"lookback_hours\", 5)\n    init_db()\n\n    entry = datetime(2026, 10, 16, 8, 0, tzinfo=UTC)\n    known_at = entry + timedelta(minutes=30)\n\n    # Terbit dan masuk sistem sebelum entry: masuk window\n    save_items([\n        _item(\"a\", \"dalam window\", entry - timedelta(hours=2)),\n        _item(\"b\", \"terlalu lama\", entry - timedelta(hours=6)),\n    ], ingested_at=entry - timedelta(hours=1))\n\n    # Terbit sebelum entry tapi baru masuk setelah known_at: dikecualikan\n    save_items([_item(\"c\", \"masuk belakangan\", entry - timedelta(hours=1))],\n               ingested_at=known_at + timedelta(minutes=5))\n\n    # Terbit setelah entry: di luar window\n    save_items([_item(\"d\", \"setelah entry\", entry + timedelta(hours=1))],\n               ingested_at=entry + timedelta(hours=1, minutes=1))\n\n    titles = [r[\"title\"] for r in build_context(entry, known_at)]\n    assert titles == [\"dalam window\"]\n\n\ndef test_dedup(tmp_path, monkeypatch):\n    monkeypatch.setattr(settings, \"db_path\", str(tmp_path / \"dedup.db\"))\n    init_db()\n\n    now = datetime(2026, 10, 16, 8, 0, tzinfo=UTC)\n    first = save_items([_item(\"x\", \"sama\", now)])\n    second = save_items([_item(\"x\", \"sama\", now)])\n    assert len(first) == 1\n    assert second == []\n",
}


def main() -> None:
    root = pathlib.Path(__file__).resolve().parent
    created = 0
    for rel, content in FILES.items():
        target = root / rel
        if target.exists():
            print(f"lewati (sudah ada): {rel}")
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        created += 1
    print(f"Selesai. {created} file dibuat.")
    print("Lanjut: pip install -r requirements.txt && python -m pytest")


if __name__ == "__main__":
    main()
